# Create function to clean_text
def clean_text(text):
    text = re.sub(r'\s+', ' ', text).translate(str.maketrans('', '', punct)).lower()
    tokens = text.split()
    tokens = [lem.lemmatize(word) for word in tokens if word not in stop]
    if len(tokens) > 2:
        return ' '.join(tokens)

